const test = require('node:test');
const assert = require('node:assert');
const { isPrime } = require('./solution.js');

test('rejects small numbers', () => {
  assert.strictEqual(isPrime(0), false);
  assert.strictEqual(isPrime(1), false);
});

test('accepts small primes', () => {
  assert.strictEqual(isPrime(2), true);
  assert.strictEqual(isPrime(3), true);
});

test('rejects composites', () => {
  assert.strictEqual(isPrime(9), false);
  assert.strictEqual(isPrime(100), false);
});

import test from "node:test";
import assert from "node:assert/strict";
import { isPrime } from "./solution";

test("rejects numbers below two", () => {
  assert.equal(isPrime(0), false);
  assert.equal(isPrime(1), false);
});

test("accepts primes", () => {
  assert.equal(isPrime(2), true);
  assert.equal(isPrime(7), true);
});

test("rejects composites", () => {
  assert.equal(isPrime(9), false);
  assert.equal(isPrime(91), false);
});

